## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/acsLogic.ts`

```typescript
/**
 * ACS Compass Clinical Logic Engine
 * Based on 2025 ACC/AHA/ACEP/NAEMSP/SCAI Guideline for the Management of Patients With Acute Coronary Syndromes
 * Rao SV et al. Circulation. 2025 Apr;151(13):e771-e834
 */

export type ACSType = 'STEMI' | 'NSTEMI' | 'UNSTABLE_ANGINA';
export type InvasiveStrategy = 'ROUTINE_INVASIVE' | 'SELECTIVE_INVASIVE' | 'PPCI' | 'FIBRINOLYTIC';
export type RiskLevel = 'LOW' | 'INTERMEDIATE' | 'HIGH';
export type P2Y12Inhibitor = 'CLOPIDOGREL' | 'PRASUGREL' | 'TICAGRELOR';
export type AnticoagulantType = 'UFH' | 'LMWH' | 'FONDAPARINUX' | 'BIVALIRUDIN';

export interface PatientData {
  // Demographics
  age: number;
  weight: number;
  sex: 'M' | 'F';

  // Presentation
  acsType: ACSType;
  symptomOnsetTime: Date;
  presentationTime: Date;

  // Risk factors
  priorMI: boolean;
  priorPCI: boolean;
  priorCABG: boolean;
  diabetes: boolean;
  hypertension: boolean;
  smoker: boolean;
  recentCocaineUse: boolean;

  // Hemodynamics
  systolicBP: number;
  heartRate: number;
  killipClass: 1 | 2 | 3 | 4;
  cardiogenicShock: boolean;

  // Labs
  troponinLevel: number; // ng/mL
  troponinElevated: boolean;
  bNPLevel?: number;
  hemoglobin: number;
  creatinine: number;

  // ECG findings
  stSegmentElevation: boolean;
  stSegmentDepression: boolean;
  tWaveInversion: boolean;
  newLBBB: boolean;

  // Bleeding risk factors
  priorStroke: boolean;
  priorTIA: boolean;
  activeBleed: boolean;
  recentSurgery: boolean;
  chronicKidneyDisease: boolean;
  onOralAnticoagulant: boolean;

  // Procedural considerations
  femurAccess: boolean;
  radialAccess: boolean;
  canAccessCathLab: boolean;
  fibrinolyticContraindication: boolean;
}

export interface ACSAssessmentResult {
  acsType: ACSType;
  riskLevel: RiskLevel;
  recommendedStrategy: InvasiveStrategy;
  recommendedP2Y12: P2Y12Inhibitor;
  recommendedAnticoagulant: AnticoagulantType;
  bleedingRisk: 'LOW' | 'MODERATE' | 'HIGH';
  timeToReperfusion: number; // minutes
  recommendations: string[];
  contraindications: string[];
  specialConsiderations: string[];
}

/**
 * Classify ACS type based on troponin and ECG findings
 */
export function classifyACSType(data: PatientData): ACSType {
  if (data.stSegmentElevation || data.newLBBB) {
    return 'STEMI';
  }
  if (data.troponinElevated) {
    return 'NSTEMI';
  }
  return 'UNSTABLE_ANGINA';
}

/**
 * Calculate NSTE-ACS risk using simplified HEART score and troponin
 */
export function calculateNSTERiskLevel(data: PatientData): RiskLevel {
  let score = 0;

  // Troponin elevation (most important)
  if (data.troponinElevated) score += 3;
  else score += 0;

  // Age
  if (data.age >= 65) score += 1;

  // Risk factors
  if (data.priorMI || data.priorPCI || data.priorCABG) score += 1;
  if (data.diabetes || data.hypertension) score += 1;

  // Hemodynamics
  if (data.killipClass >= 2) score += 2;

  // ECG changes
  if (data.stSegmentDepression) score += 1;
  if (data.tWaveInversion) score += 1;

  // BNP elevation if available
  if (data.bNPLevel && data.bNPLevel > 100) score += 1;

  if (score >= 6) return 'HIGH';
  if (score >= 3) return 'INTERMEDIATE';
  return 'LOW';
}

/**
 * Assess bleeding risk using simplified PRECISE-DAPT and HAS-BLED
 */
export function assessBleedingRisk(data: PatientData): 'LOW' | 'MODERATE' | 'HIGH' {
  let score = 0;

  // Age
  if (data.age >= 75) score += 2;
  else if (data.age >= 65) score += 1;

  // Renal function
  if (data.creatinine > 2.0) score += 2;
  else if (data.creatinine > 1.5) score += 1;

  // Hemoglobin
  if (data.hemoglobin < 10) score += 2;
  else if (data.hemoglobin < 11) score += 1;

  // Prior stroke/TIA
  if (data.priorStroke || data.priorTIA) score += 2;

  // Active bleeding or recent surgery
  if (data.activeBleed || data.recentSurgery) score += 2;

  // Chronic kidney disease
  if (data.chronicKidneyDisease) score += 1;

  // On oral anticoagulant
  if (data.onOralAnticoagulant) score += 1;

  if (score >= 5) return 'HIGH';
  if (score >= 2) return 'MODERATE';
  return 'LOW';
}

/**
 * Recommend P2Y12 inhibitor based on bleeding risk and patient factors
 */
export function recommendP2Y12Inhibitor(data: PatientData, bleedingRisk: string): P2Y12Inhibitor {
  // Contraindications to prasugrel/ticagrelor
  if (data.priorStroke || data.priorTIA || data.age >= 75 || data.weight < 60) {
    return 'CLOPIDOGREL';
  }

  // High bleeding risk
  if (bleedingRisk === 'HIGH') {
    return 'CLOPIDOGREL';
  }

  // STEMI: prefer prasugrel or ticagrelor
  if (data.acsType === 'STEMI') {
    return 'PRASUGREL';
  }

  // NSTEMI: ticagrelor preferred
  return 'TICAGRELOR';
}

/**
 * Recommend anticoagulant based on renal function and bleeding risk
 */
export function recommendAnticoagulant(data: PatientData, bleedingRisk: string): AnticoagulantType {
  // High bleeding risk: consider fondaparinux
  if (bleedingRisk === 'HIGH') {
    if (data.creatinine <= 3.0) {
      return 'FONDAPARINUX';
    }
    return 'UFH';
  }

  // Moderate bleeding risk: LMWH or UFH
  if (bleedingRisk === 'MODERATE') {
    if (data.creatinine > 2.0) {
      return 'UFH';
    }
    return 'LMWH';
  }

  // Low bleeding risk: bivalirudin for PCI
  if (data.acsType === 'STEMI' && data.canAccessCathLab) {
    return 'BIVALIRUDIN';
  }

  return 'UFH';
}

/**
 * Recommend invasive strategy for NSTE-ACS
 */
export function recommendNSTEInvasiveStrategy(data: PatientData, riskLevel: RiskLevel): InvasiveStrategy {
  // High-risk: routine invasive within 24 hours
  if (riskLevel === 'HIGH') {
    return 'ROUTINE_INVASIVE';
  }

  // Intermediate-risk: routine invasive
  if (riskLevel === 'INTERMEDIATE') {
    return 'ROUTINE_INVASIVE';
  }

  // Low-risk: selective invasive with further risk stratification
  return 'SELECTIVE_INVASIVE';
}

/**
 * Recommend reperfusion strategy for STEMI
 */
export function recommendSTEMIReperfusion(data: PatientData): InvasiveStrategy {
  // Primary PCI is preferred if available within 120 minutes
  if (data.canAccessCathLab) {
    const doorToBallon = 90; // minutes
    const symptomOnsetToPresentation = Math.round(
      (data.presentationTime.getTime() - data.symptomOnsetTime.getTime()) / 60000
    );

    // If total time to balloon <120 min, use PPCI
    if (symptomOnsetToPresentation + doorToBallon <= 120) {
      return 'PPCI';
    }
  }

  // Fibrinolytic if PPCI not available or delayed
  if (!data.fibrinolyticContraindication) {
    return 'FIBRINOLYTIC';
  }

  // If both unavailable, refer for urgent PPCI
  return 'PPCI';
}

/**
 * Generate vascular access recommendation
 */
export function recommendVascularAccess(data: PatientData): string {
  // Radial preferred for ACS to reduce bleeding
  if (data.radialAccess) {
    return 'Radial approach preferred (reduces bleeding and vascular complications)';
  }

  if (data.femurAccess) {
    return 'Femoral approach acceptable if radial unavailable';
  }

  return 'Radial approach strongly recommended for ACS';
}

/**
 * Main assessment function
 */
export function assessACS(data: PatientData): ACSAssessmentResult {
  const acsType = classifyACSType(data);
  const riskLevel = acsType === 'STEMI' ? 'HIGH' : calculateNSTERiskLevel(data);
  const bleedingRisk = assessBleedingRisk(data);
  const p2y12 = recommendP2Y12Inhibitor(data, bleedingRisk);
  const anticoagulant = recommendAnticoagulant(data, bleedingRisk);

  let strategy: InvasiveStrategy;
  let timeToReperfusion: number;

  if (acsType === 'STEMI') {
    strategy = recommendSTEMIReperfusion(data);
    timeToReperfusion = strategy === 'PPCI' ? 90 : 30; // door-to-balloon or door-to-needle
  } else {
    strategy = recommendNSTEInvasiveStrategy(data, riskLevel);
    timeToReperfusion = strategy === 'ROUTINE_INVASIVE' ? 240 : 0; // 4 hours for routine invasive
  }

  const recommendations: string[] = [];
  const contraindications: string[] = [];
  const specialConsiderations: string[] = [];

  // Generate recommendations
  recommendations.push(`ACS Type: ${acsType}`);
  recommendations.push(`Risk Level: ${riskLevel}`);
  recommendations.push(`Recommended Strategy: ${strategy}`);
  recommendations.push(`P2Y12 Inhibitor: ${p2y12}`);
  recommendations.push(`Anticoagulant: ${anticoagulant}`);
  recommendations.push(recommendVascularAccess(data));

  // Dual antiplatelet therapy (aspirin + P2Y12)
  recommendations.push('Dual antiplatelet therapy (aspirin + P2Y12 inhibitor) for ≥12 months');

  // High-intensity statin
  recommendations.push('High-intensity statin therapy (atorvastatin 80 mg or rosuvastatin 40 mg daily)');

  // Bleeding prevention
  if (bleedingRisk === 'HIGH') {
    recommendations.push('Proton pump inhibitor for GI bleeding prevention');
    specialConsiderations.push('High bleeding risk: consider ticagrelor monotherapy ≥1 month post-PCI');
  }

  // Cardiogenic shock
  if (data.cardiogenicShock) {
    specialConsiderations.push('Cardiogenic shock present: emergency revascularization of culprit vessel indicated');
    specialConsiderations.push('Consider mechanical circulatory support (microaxial flow pump) in selected cases');
  }

  // Anemia management
  if (data.hemoglobin < 10) {
    specialConsiderations.push(`Hemoglobin ${data.hemoglobin} g/dL: consider transfusion to maintain Hgb ≥10 g/dL`);
  }

  // Contraindications
  if (data.fibrinolyticContraindication && acsType === 'STEMI') {
    contraindications.push('Fibrinolytic contraindication present');
  }

  if (data.priorStroke || data.priorTIA) {
    contraindications.push('Prior stroke/TIA: prasugrel contraindicated');
  }

  return {
    acsType,
    riskLevel,
    recommendedStrategy: strategy,
    recommendedP2Y12: p2y12,
    recommendedAnticoagulant: anticoagulant,
    bleedingRisk,
    timeToReperfusion,
    recommendations,
    contraindications,
    specialConsiderations,
  };
}
